#ifndef TCPE_JAVA_PACK_SOUND_DECODE_H
#define TCPE_JAVA_PACK_SOUND_DECODE_H
#include "JavaPackSounds.h"
#include "../JavaServerConnection.h"
#include <cmath>
#include <algorithm>
inline bool javaSoundName(const std::string&name){auto colon=name.find(':');if(colon==std::string::npos||colon==0||colon+1>=name.size()||name.size()>256)return false;for(size_t i=0;i<name.size();++i){char c=name[i];if(i==colon)continue;if((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_'||c=='-'||c=='.'||(i>colon&&c=='/'))continue;return false;}return true;}
inline bool javaSoundFile(const std::string&file){return file.size()==28&&file.substr(24)==".wav"&&std::all_of(file.begin(),file.begin()+24,[](char c){return (c>='0'&&c<='9')||(c>='a'&&c<='f');});}
inline bool decodeJavaSoundPcm(const std::string&encoded,std::vector<unsigned char>&out){out.clear();if(encoded.empty()||encoded.size()>((16*1024*1024+2)/3)*4||encoded.size()%4)return false;const std::string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";for(size_t i=0;i<encoded.size();i+=4){unsigned value=0;int padding=0;for(int j=0;j<4;++j){char c=encoded[i+j];if(c=='='){if(i+4!=encoded.size()||j<2)return false;++padding;value<<=6;}else{if(padding)return false;auto index=alphabet.find(c);if(index==std::string::npos)return false;value=(value<<6)|unsigned(index);}}if(padding>2)return false;out.push_back(value>>16);if(padding<2)out.push_back(value>>8);if(!padding)out.push_back(value);}return !out.empty()&&out.size()<=16*1024*1024;}
inline bool readJavaPackSounds(const JavaServerConnection&c,const std::string&root,JavaPackSounds&out,size_t&bytes){size_t count=0;if(c.arraySize(root+".definitions",count)){if(count>4096)return false;for(size_t i=0;i<count;++i){JavaPackSoundDefinition d;const auto path=root+".definitions."+std::to_string(i);if(!c.text(path+".name",d.name)||!javaSoundName(d.name))return false;c.boolean(path+".replace",d.replace);size_t variants=0;if(!c.arraySize(path+".variants",variants)||variants>512)return false;for(size_t j=0;j<variants;++j){JavaPackSoundVariant v;auto p=path+".variants."+std::to_string(j);double weight=0,volume=1,pitch=1,distance=16;if(!c.text(p+".name",v.name)||!javaSoundName(v.name)||!c.text(p+".kind",v.kind)||(v.kind!="file"&&v.kind!="event")||!c.number(p+".weight",weight)||!std::isfinite(weight)||weight<1||weight>100000||std::floor(weight)!=weight||!c.number(p+".volume",volume)||!std::isfinite(volume)||volume<=0||volume>100000||!c.number(p+".pitch",pitch)||!std::isfinite(pitch)||pitch<=0||pitch>100000||!c.number(p+".attenuation_distance",distance)||!std::isfinite(distance)||distance<=0||distance>100000)return false;v.weight=uint32_t(weight);v.volume=volume;v.pitch=pitch;v.attenuationDistance=distance;d.variants.push_back(std::move(v));}out.definitions.push_back(std::move(d));}}
 if(c.arraySize(root+".samples",count)){if(count>4096)return false;size_t soundBytes=0;for(size_t i=0;i<count;++i){JavaPackSoundSample sample;auto p=root+".samples."+std::to_string(i);std::string encoded;double channels=0,rate=0;if(!c.text(p+".name",sample.name)||!javaSoundName(sample.name)||!c.text(p+".file",sample.file)||!javaSoundFile(sample.file)||!c.number(p+".channels",channels)||(channels!=1&&channels!=2)||!c.number(p+".rate",rate)||!std::isfinite(rate)||rate<8000||rate>192000||std::floor(rate)!=rate||!c.text(p+".pcm_base64",encoded)||!decodeJavaSoundPcm(encoded,sample.pcm))return false;sample.channels=int(channels);sample.rate=int(rate);if(sample.pcm.size()%(sample.channels*2))return false;soundBytes+=sample.pcm.size();if(soundBytes>64*1024*1024||bytes>256*1024*1024-sample.pcm.size())return false;bytes+=sample.pcm.size();out.samples.push_back(std::move(sample));}}
 // Empty internal sample.file is a validated unavailable-file marker, not PCM.
 if(c.arraySize(root+".unavailable_files",count)){if(count>4096||out.samples.size()>4096-count)return false;for(size_t i=0;i<count;++i){JavaPackSoundSample missing;if(!c.text(root+".unavailable_files."+std::to_string(i),missing.name)||!javaSoundName(missing.name))return false;out.samples.push_back(std::move(missing));}}
 if(c.arraySize(root+".errors",count)){if(count>128)return false;for(size_t i=0;i<count;++i){std::string error;if(c.text(root+".errors."+std::to_string(i),error))out.errors.push_back(error.substr(0,512));}}return true;}
#endif
